import 'package:mercury_client/mercury_client.dart';

main() async {
  var client = HttpClient('http://gateway.your.domain/api-1');

  try {
    var response = await client.post(
      'call-foo',
      parameters: {'var': '123'},
      body: "{ 'content': 'any' }",
      contentType: 'application/json',
    );

    if (response.isOK) {
      print(response.body);
    }
  } catch (e) {
    print('Error requesting URL: $e');
  }
}
